function demoMain(idx,label){
  var policies=[["open","read","write"],["read","write"],["open","read","socket"],["read"]];
  var calls=["open","read","write","socket","exec"]; var allow=policies[idx%policies.length];
  var res=calls.map(function(c){return c+":"+(allow.indexOf(c)>=0?"ALLOW":"DENY");});
  return "["+label+"] policy ["+allow.join(",")+"] => "+res.join(" ");
}

